  for (int y = 0; y < 101; y++)
    for (int x = 0; x < 101; x++) {
      TEST_ASSERT_EQUAL_INT(halo_get_bit(plane(p), x, y),
                            halo_get_bit(plane(p), 100 - x, 100 - y));
      TEST_ASSERT_EQUAL_INT(halo_get_bit(plane(p), x, y),
                            halo_get_bit(plane(p), y, x));
    }
  for (int y = 0; y < 101; y++) {
    int first = -1, last = -1;
    for (int x = 0; x < 101; x++)
      if (halo_get_bit(plane(p), x, y)) {
        if (first < 0) first = x;
        last = x;
